"use client";

import Link from "next/link";
import { useRouter, useSearchParams } from "next/navigation";
import { useState } from "react";
import { authClient } from "@/lib/auth-client";

// Only allow same-site relative paths as a post-login destination.
function safeNext(next: string | null) {
  return next && next.startsWith("/") && !next.startsWith("//") ? next : "/dashboard";
}

export function AuthForm({ mode }: { mode: "sign-in" | "sign-up" }) {
  const router = useRouter();
  const next = safeNext(useSearchParams().get("next"));
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const isSignUp = mode === "sign-up";

  async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const email = String(form.get("email"));
    const password = String(form.get("password"));

    setPending(true);
    setError(null);
    const { error } = isSignUp
      ? await authClient.signUp.email({ name: String(form.get("name")), email, password })
      : await authClient.signIn.email({ email, password });
    setPending(false);

    if (error) {
      setError(error.message ?? "Something went wrong");
      return;
    }
    router.push(next);
    router.refresh();
  }

  async function onGoogle() {
    setError(null);
    const { error } = await authClient.signIn.social({ provider: "google", callbackURL: next });
    if (error) setError(error.message ?? "Google sign-in failed");
  }

  const input =
    "w-full rounded border border-black/15 bg-transparent px-3 py-2 text-sm dark:border-white/20";

  return (
    <main className="mx-auto w-full max-w-sm p-8">
      <h1 className="text-2xl font-semibold">{isSignUp ? "Create your account" : "Sign in"}</h1>

      <form onSubmit={onSubmit} className="mt-6 space-y-3">
        {isSignUp && (
          <input name="name" placeholder="Name" required autoComplete="name" className={input} />
        )}
        <input
          name="email"
          type="email"
          placeholder="Email"
          required
          autoComplete="email"
          className={input}
        />
        <input
          name="password"
          type="password"
          placeholder="Password"
          required
          minLength={8}
          autoComplete={isSignUp ? "new-password" : "current-password"}
          className={input}
        />
        {error && <p className="text-sm text-red-600">{error}</p>}
        <button
          type="submit"
          disabled={pending}
          className="w-full rounded bg-foreground px-3 py-2 text-sm font-medium text-background disabled:opacity-50"
        >
          {pending ? "…" : isSignUp ? "Sign up" : "Sign in"}
        </button>
      </form>

      <button
        type="button"
        onClick={onGoogle}
        className="mt-3 w-full rounded border border-black/15 px-3 py-2 text-sm font-medium hover:bg-black/5 dark:border-white/20 dark:hover:bg-white/10"
      >
        Continue with Google
      </button>

      <p className="mt-6 text-sm opacity-70">
        {isSignUp ? (
          <>
            Already have an account? <Link href={`/sign-in?next=${encodeURIComponent(next)}`} className="underline">Sign in</Link>
          </>
        ) : (
          <>
            No account yet? <Link href={`/sign-up?next=${encodeURIComponent(next)}`} className="underline">Sign up</Link>
          </>
        )}
      </p>
    </main>
  );
}
